-- seed-state-legislators batch 02
-- States: HI, ID, IL, IN, IA, KS, KY, LA, ME, MD
-- Paste into Supabase SQL Editor AFTER migration-selection-method-and-legislative.sql
-- Safe to re-run for these states.

delete from public.state_officials
where court_or_agency = 'Legislative Branch'
  and state_code in ('HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD');

insert into public.state_officials (
  full_name,
  title,
  court_or_agency,
  level,
  state_code,
  district_number,
  county_name,
  party,
  photo_url,
  selection_method,
  appointed_by
)
